from sethelp import *
def src(book,t,pages): return "%s · Answer Booklet Test %d, Speaking (tr.%s) · hình: Student's Book, Test %d Speaking"%(book,t,pages,t)
def cardsdict(sid,items): return {k:card(sid,k,w,s) for k,w,s in items}
